function lotTrackingHTML(i){
 const lots=i.lots.filter(l=>l.qty>0).sort((a,b)=>a.received.localeCompare(b.received)||a.expiry.localeCompare(b.expiry));
 const title=i.source==='manager'?(i.allocationMethod==='FIFO'?'선입선출 기준 잔량 추적':'기존 정책으로 저장된 묶음별 잔량'):'제공 기록의 묶음별 잔량';
 return `<section class="lot-tracking"><div class="lot-tracking-heading"><h3>${title}</h3><span class="badge ${i.source==='manager'?'excess':''}">${i.source==='manager'?'가정 기반 추정':'제공 기록'}</span></div><div class="lot-tracking-total">남은 ${qty(i.stock,i)} <small>· ${lots.length}개 입고 묶음</small></div><table><thead><tr><th>입고일</th><th>남은 수량</th><th>마지막 사용일</th><th>남은 일수</th></tr></thead><tbody>${lots.map(l=>{const remaining=days(state.date,l.expiry);return `<tr><td>${l.received}</td><td><b>${qty(l.qty,i)}</b></td><td>${l.expiry}</td><td><span class="${remaining<=3?'expiry-warn':''}">${remaining<0?'기한 경과':remaining===0?'오늘까지':remaining+'일 후'}</span></td></tr>`}).join('')||'<tr><td colspan="4">남은 입고 묶음 없음</td></tr>'}</tbody></table><p class="lot-day-note">선택일 ${state.date}부터 마지막 사용일까지의 날짜 차이입니다. 마지막 사용일 당일에도 사용 가능하며 마감 후 잔량을 폐기합니다.</p>${i.source==='manager'?`<div class="explanation">${i.allocationMethod==='FIFO'?'먼저 입고된 재고부터 사용·폐기했다고 가정해 총잔량을 배분했습니다.':'이전 버전의 사용기한 우선 소진 가정으로 저장한 기록입니다. 새로 저장하는 기록부터 선입선출을 적용합니다.'} 기존 입고일과 사용기한은 유지합니다. 총잔량만으로 실제 사용한 묶음을 확인한 결과는 아닙니다.</div>`:''}${i.lotTrace?.length?`<details class="lot-audit"><summary>어떻게 이 잔량이 나왔나요?</summary><div class="table-wrap"><table><thead><tr><th>입고일</th><th>차감 전</th><th>추정 감소</th><th>폐기 배분</th><th>잔량</th></tr></thead><tbody>${i.lotTrace.map(l=>`<tr><td>${l.received}</td><td>${qty(l.before,i)}</td><td>${qty(l.used,i)}</td><td>${qty(l.wasted,i)}</td><td>${qty(l.qty,i)}</td></tr>`).join('')}</tbody></table></div><p class="lot-day-note">추정 감소에는 판매 사용과 실사 차이가 함께 포함될 수 있습니다.</p></details>`:''}</section>`;
}
function openTrackingPreview(p,result,input){
 const preview={...p,source:'manager',allocationMethod:'FIFO',stock:Number(input.closing),lots:result.lots,lotTrace:result.trail};
 showDrawer(`<div class="drawer-header"><div><div class="eyebrow">FIFO LOT TRACKING</div><h2>${escapeHTML(p.ingredient_name)}</h2><p>${state.date} 입력값 기준 · 저장 전 미리보기</p></div><button class="icon-button close-drawer" aria-label="닫기">×</button></div><div class="tracking-formula"><span>이전 잔량 ${qty(p.stock,p)}</span><span>+ 입고 ${qty(Number(input.received),p)}</span><span>− 폐기 ${qty(Number(input.waste),p)}</span><span>− 추정 감소 ${qty(result.consumed,p)}</span><strong>= 남은 ${qty(Number(input.closing),p)}</strong></div>${lotTrackingHTML(preview)}<div class="explanation">미리보기는 아직 저장되지 않았습니다. 창을 닫고 전체 품목의 수량을 확인한 뒤 ‘마감 재고 저장’을 눌러주세요.</div>`);
}
